function detectLang(){
  const hash=window.location.hash;
  if(hash==='#/уз')return 'cy';
  if(hash==='#/uz')return 'uz';
  if(hash==='#/ru')return 'ru';
  if(hash==='#/en')return 'en';
  const saved=localStorage.getItem('gf_lang');
  if(saved)return saved;
  const bl=(navigator.language||'uz').toLowerCase();
  if(bl.startsWith('ru'))return 'ru';
  if(bl.startsWith('en'))return 'en';
  return 'uz';
}
let currentLang=detectLang();
function setLang(lang){
  currentLang=lang;
  localStorage.setItem('gf_lang',lang);
  const m={uz:'#/uz',cy:'#/уз',ru:'#/ru',en:'#/en'};
  history.replaceState(null,'',window.location.pathname+m[lang]);
  applyTranslations();updateLangButtons();renderProducts();
}
function t(key){return(translations[currentLang]&&translations[currentLang][key])||(translations['uz']&&translations['uz'][key])||key;}
function applyTranslations(){
  document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t(el.getAttribute('data-i18n'));});
  document.querySelectorAll('[data-i18n-ph]').forEach(el=>{el.placeholder=t(el.getAttribute('data-i18n-ph'));});
  const m={uz:'uz',cy:'uz-Cyrl',ru:'ru',en:'en'};
  document.documentElement.lang=m[currentLang]||'uz';
}
function updateLangButtons(){
  document.querySelectorAll('.lang-btn').forEach(btn=>{btn.classList.toggle('active',btn.dataset.lang===currentLang);});
}

// =============================================
// PRODUCTS RENDER
// =============================================
function pName(p){return p.name[currentLang]||p.name.uz;}
function pDesc(p){return p.desc[currentLang]||p.desc.uz;}
function pBadge(p){return p.badge[currentLang]||p.badge.uz;}

function renderProducts(){
  const grid=document.getElementById('productGrid');
  if(!grid)return;
  grid.innerHTML=productsData.map((p,idx)=>{
    const imgCount=p.images.length+(p.video?1:0);
    return `<div class="product-card" onclick="openProduct(${idx})">
      <div class="product-image">
        <img src="${p.images[0]}" alt="${pName(p)}" loading="lazy" onerror="this.src='https://images.unsplash.com/photo-1555041469-a586c61ea9bc?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=600'">
        <div class="product-badge">${pBadge(p)}</div>
        <div class="product-img-count">
          <svg width="12" height="12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
          &nbsp;${imgCount}
        </div>
      </div>
      <div class="product-content">
        <div class="product-rating"><span class="star">★</span><span class="star">★</span><span class="star">★</span><span class="star">★</span><span class="star">★</span></div>
        <h3 class="product-title">${pName(p)}</h3>
        <p class="product-description">${pDesc(p)}</p>
        <div class="product-dims"><span class="dim-tag">${p.sizes}</span></div>
        <div class="product-footer">
          <button class="btn-learn-more" onclick="event.stopPropagation();openProduct(${idx})">${t('prod_detail')}</button>
        </div>
      </div>
    </div>`;
  }).join('');
}

// =============================================
// MODAL
// =============================================
let curProd=0,curMedia=0;
// media array: images + optional video at end
function getMediaList(p){
  const list=p.images.map(src=>({type:'image',src}));
  if(p.video)list.push({type:'video',src:p.video});
  return list;
}

function openProduct(idx){
  curProd=idx;curMedia=0;
  refreshModal();
  document.getElementById('productModal').classList.add('active');
  document.body.style.overflow='hidden';
}
function closeProduct(){
  // pause any video
  const v=document.querySelector('#productModal video');
  if(v)v.pause();
  document.getElementById('productModal').classList.remove('active');
  document.body.style.overflow='';
}
function refreshModal(){
  const p=productsData[curProd];
  const media=getMediaList(p);
  const current=media[curMedia];
  const thumbsHtml=media.map((m,i)=>{
    if(m.type==='video'){
      return `<div class="thumb ${i===curMedia?'active':''}" onclick="setMedia(${i})" title="Video">
        <div style="width:100%;height:100%;background:#302b2b;display:flex;align-items:center;justify-content:center;">
          <svg width="20" height="20" fill="white" viewBox="0 0 24 24"><polygon points="5 3 19 12 5 21 5 3"/></svg>
        </div>
      </div>`;
    }
    return `<div class="thumb ${i===curMedia?'active':''}" onclick="setMedia(${i})"><img src="${m.src}" alt="" onerror="this.parentElement.style.display='none'"></div>`;
  }).join('');

  const mainContent=current.type==='video'
    ?`<video controls playsinline preload="metadata" style="width:100%;height:100%;object-fit:contain;background:#000;" poster="${p.images[0]}">
        <source src="${current.src}" type="video/mp4">
        <source src="${current.src}" type="video/quicktime">
      </video>`
    :`<img id="modalMainImg" src="${current.src}" alt="${pName(p)}" onerror="this.src='https://images.unsplash.com/photo-1555041469-a586c61ea9bc?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&q=80&w=800'">`;

  document.querySelector('#productModal .modal-inner').innerHTML=`
    <button class="modal-close" onclick="closeProduct()">
      <svg width="24" height="24" fill="none" stroke="currentColor" viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
    </button>
    <div class="modal-body">
      <div class="modal-gallery">
        <div class="modal-main-img">
          ${mainContent}
          ${media.length>1?`
          <button class="gallery-nav prev" onclick="changeMedia(-1)"><svg width="22" height="22" fill="none" stroke="currentColor" viewBox="0 0 24 24"><polyline points="15 18 9 12 15 6"/></svg></button>
          <button class="gallery-nav next" onclick="changeMedia(1)"><svg width="22" height="22" fill="none" stroke="currentColor" viewBox="0 0 24 24"><polyline points="9 18 15 12 9 6"/></svg></button>`:''}
        </div>
        <div class="modal-thumbs">${thumbsHtml}</div>
      </div>
      <div class="modal-info">
        <div class="modal-badge">${pBadge(p)}</div>
        <h2 class="modal-title">${pName(p)}</h2>
        <div class="modal-rating">★★★★★</div>
        <p class="modal-desc">${pDesc(p)}</p>
        <div class="modal-sizes">
          <div class="size-row"><span class="size-label">${t('prod_size')}:</span><span class="size-val">${p.sizes}</span></div>
        </div>
        <button class="btn btn-primary btn-full modal-order-btn" onclick="closeProduct();scrollToSection('contact')">
          ${t('prod_contact')}
          <svg class="icon-arrow" fill="none" stroke="currentColor" viewBox="0 0 24 24" width="20" height="20"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 8l4 4m0 0l-4 4m4-4H3"/></svg>
        </button>
      </div>
    </div>`;
}
function setMedia(i){curMedia=i;refreshModal();}
function changeMedia(d){
  const p=productsData[curProd];
  const len=getMediaList(p).length;
  curMedia=(curMedia+d+len)%len;
  refreshModal();
}

// =============================================
// MOBILE MENU
// =============================================
function toggleMobileMenu(){
  const menu=document.getElementById('mobileMenu');
  const overlay=document.getElementById('mobileMenuOverlay');
  const open=menu.classList.toggle('open');
  overlay.classList.toggle('open',open);
  document.body.style.overflow=open?'hidden':'';
}
function closeMobileMenu(){
  document.getElementById('mobileMenu').classList.remove('open');
  document.getElementById('mobileMenuOverlay').classList.remove('open');
  document.body.style.overflow='';
}

// =============================================
// SCROLL
// =============================================
function scrollToSection(id){
  closeMobileMenu();
  const el=document.getElementById(id);
  if(!el)return;
  const hh=document.querySelector('.header').offsetHeight;
  window.scrollTo({top:el.getBoundingClientRect().top+window.pageYOffset-hh,behavior:'smooth'});
}

// =============================================
// INIT
// =============================================
document.addEventListener('DOMContentLoaded',function(){
  currentLang=detectLang();
  applyTranslations();updateLangButtons();renderProducts();

  const contactForm=document.getElementById('contactForm');
  if(contactForm){
    contactForm.addEventListener('submit',function(e){
      e.preventDefault();
      const btn=this.querySelector('button[type="submit"]');
      btn.disabled=true;btn.style.opacity='0.7';
      setTimeout(()=>{
        const msg=document.getElementById('formSuccess');
        if(msg){msg.style.display='flex';}
        contactForm.reset();
        btn.disabled=false;btn.style.opacity='';
        setTimeout(()=>{if(msg)msg.style.display='none';},5000);
      },600);
    });
  }

  const observer=new IntersectionObserver(entries=>{
    entries.forEach(e=>{if(e.isIntersecting){e.target.style.opacity='1';e.target.style.transform='translateY(0)';}});
  },{threshold:0.08,rootMargin:'0px 0px -30px 0px'});
  document.querySelectorAll('.feature-card,.category-card,.review-card,.step-card,.why-card').forEach(el=>{
    el.style.opacity='0';el.style.transform='translateY(20px)';el.style.transition='opacity 0.6s ease,transform 0.6s ease';
    observer.observe(el);
  });

  const header=document.querySelector('.header');
  window.addEventListener('scroll',()=>{
    header.style.boxShadow=window.pageYOffset>80?'0 2px 20px rgba(0,0,0,0.12)':'none';
  });

  document.getElementById('productModal').addEventListener('click',function(e){
    if(e.target===this)closeProduct();
  });

  document.addEventListener('click',function(e){
    const menu=document.getElementById('mobileMenu');
    const btn=document.querySelector('.mobile-menu-btn');
    if(menu.classList.contains('open')&&!menu.contains(e.target)&&!btn.contains(e.target))closeMobileMenu();
  });

  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){closeProduct();closeMobileMenu();}
    const modal=document.getElementById('productModal');
    if(!modal.classList.contains('active'))return;
    if(e.key==='ArrowLeft')changeMedia(-1);
    if(e.key==='ArrowRight')changeMedia(1);
  });
});
